export function App() {
  return (
    <main className="shell">
      <section className="placeholder" aria-labelledby="starter-title">
        <p className="eyebrow">AgentCofounder</p>
        <h1 id="starter-title">Ready to build</h1>
        <p>
          This neutral application seed is replaced by the participant harness during a challenge run.
        </p>
      </section>
    </main>
  );
}

/**
 * Domain-neutral, accessible UI primitives. Every control has a real label or accessible
 * name so a browser-driven judge can find it without brittle selectors.
 */
import {
  useEffect,
  useId,
  useRef,
  type ButtonHTMLAttributes,
  type FormHTMLAttributes,
  type InputHTMLAttributes,
  type ReactNode,
  type SelectHTMLAttributes,
  type TextareaHTMLAttributes,
} from "react";

export function AppShell({
  title,
  description,
  toolbar,
  children,
}: {
  title: string;
  description?: string;
  toolbar?: ReactNode;
  children: ReactNode;
}) {
  return (
    <div className="shell">
      <header className="shell__header">
        <div>
          <h1>{title}</h1>
          {description ? <p className="shell__description">{description}</p> : null}
        </div>
        {toolbar ? <div className="shell__toolbar">{toolbar}</div> : null}
      </header>
      <main className="shell__main">{children}</main>
    </div>
  );
}

export function Section({
  title,
  actions,
  children,
}: {
  title: string;
  actions?: ReactNode;
  children: ReactNode;
}) {
  const headingId = useId();
  return (
    <section className="card" aria-labelledby={headingId}>
      <div className="card__header">
        <h2 id={headingId}>{title}</h2>
        {actions ? <div className="card__actions">{actions}</div> : null}
      </div>
      {children}
    </section>
  );
}

export function StatCard({ label, value }: { label: string; value: ReactNode }) {
  return (
    <div className="stat">
      <span className="stat__label">{label}</span>
      <strong className="stat__value">{value}</strong>
    </div>
  );
}

export function Button({
  variant = "primary",
  type = "button",
  ...props
}: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: "primary" | "secondary" | "danger" }) {
  return <button type={type} className={`button button--${variant}`} {...props} />;
}

export function Form({ children, ...props }: FormHTMLAttributes<HTMLFormElement>) {
  return (
    <form noValidate className="form" {...props}>
      {children}
    </form>
  );
}

interface FieldShell {
  label: string;
  error?: string | undefined;
  hint?: string;
}

export function TextField({
  label,
  error,
  hint,
  ...props
}: FieldShell & InputHTMLAttributes<HTMLInputElement>) {
  const id = useId();
  const errorId = `${id}-error`;
  const hintId = `${id}-hint`;
  return (
    <div className="field">
      <label htmlFor={id}>{label}</label>
      <input
        id={id}
        aria-invalid={error ? true : undefined}
        aria-describedby={[error ? errorId : undefined, hint ? hintId : undefined].filter(Boolean).join(" ") || undefined}
        {...props}
      />
      {hint ? (
        <p id={hintId} className="field__hint">
          {hint}
        </p>
      ) : null}
      {error ? (
        <p id={errorId} className="field__error" role="alert">
          {error}
        </p>
      ) : null}
    </div>
  );
}

export function TextAreaField({
  label,
  error,
  hint,
  ...props
}: FieldShell & TextareaHTMLAttributes<HTMLTextAreaElement>) {
  const id = useId();
  const errorId = `${id}-error`;
  return (
    <div className="field">
      <label htmlFor={id}>{label}</label>
      <textarea id={id} aria-invalid={error ? true : undefined} aria-describedby={error ? errorId : undefined} {...props} />
      {hint ? <p className="field__hint">{hint}</p> : null}
      {error ? (
        <p id={errorId} className="field__error" role="alert">
          {error}
        </p>
      ) : null}
    </div>
  );
}

export function SelectField({
  label,
  error,
  hint,
  options,
  ...props
}: FieldShell & SelectHTMLAttributes<HTMLSelectElement> & { options: readonly { value: string; label: string }[] }) {
  const id = useId();
  const errorId = `${id}-error`;
  return (
    <div className="field">
      <label htmlFor={id}>{label}</label>
      <select id={id} aria-invalid={error ? true : undefined} aria-describedby={error ? errorId : undefined} {...props}>
        {options.map((option) => (
          <option key={option.value} value={option.value}>
            {option.label}
          </option>
        ))}
      </select>
      {hint ? <p className="field__hint">{hint}</p> : null}
      {error ? (
        <p id={errorId} className="field__error" role="alert">
          {error}
        </p>
      ) : null}
    </div>
  );
}

export function Notice({
  tone = "info",
  children,
  onDismiss,
}: {
  tone?: "info" | "warning" | "error" | "success";
  children: ReactNode;
  onDismiss?: () => void;
}) {
  return (
    <div className={`notice notice--${tone}`} role={tone === "error" || tone === "warning" ? "alert" : "status"}>
      <span>{children}</span>
      {onDismiss ? (
        <button type="button" className="notice__dismiss" onClick={onDismiss} aria-label="Dismiss message">
          ×
        </button>
      ) : null}
    </div>
  );
}

export function EmptyState({
  title,
  description,
  action,
}: {
  title: string;
  description?: string;
  action?: ReactNode;
}) {
  return (
    <div className="empty" role="status">
      <p className="empty__title">{title}</p>
      {description ? <p className="empty__description">{description}</p> : null}
      {action}
    </div>
  );
}

export function DataList<Record_ extends { id: string }>({
  items,
  renderItem,
  label,
  empty,
}: {
  items: readonly Record_[];
  renderItem: (item: Record_) => ReactNode;
  label: string;
  empty: ReactNode;
}) {
  if (items.length === 0) return <>{empty}</>;
  return (
    <ul className="list" aria-label={label}>
      {items.map((item) => (
        <li key={item.id} className="list__item">
          {renderItem(item)}
        </li>
      ))}
    </ul>
  );
}

export function DataTable<Record_ extends { id: string }>({
  caption,
  columns,
  rows,
  empty,
}: {
  caption: string;
  columns: readonly { key: string; header: string; render: (row: Record_) => ReactNode }[];
  rows: readonly Record_[];
  empty: ReactNode;
}) {
  if (rows.length === 0) return <>{empty}</>;
  return (
    <div className="table-wrap">
      <table className="table">
        <caption>{caption}</caption>
        <thead>
          <tr>
            {columns.map((column) => (
              <th key={column.key} scope="col">
                {column.header}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <tr key={row.id}>
              {columns.map((column) => (
                <td key={column.key}>{column.render(row)}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export function Dialog({
  open,
  title,
  onClose,
  children,
}: {
  open: boolean;
  title: string;
  onClose: () => void;
  children: ReactNode;
}) {
  const headingId = useId();
  const container = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return undefined;
    const onKeyDown = (event: KeyboardEvent): void => {
      if (event.key === "Escape") onClose();
    };
    document.addEventListener("keydown", onKeyDown);
    container.current?.focus();
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [onClose, open]);

  if (!open) return null;
  return (
    <div className="dialog__backdrop">
      <div
        className="dialog"
        role="dialog"
        aria-modal="true"
        aria-labelledby={headingId}
        ref={container}
        tabIndex={-1}
      >
        <div className="dialog__header">
          <h2 id={headingId}>{title}</h2>
          <button type="button" onClick={onClose} aria-label="Close dialog" className="notice__dismiss">
            ×
          </button>
        </div>
        {children}
      </div>
    </div>
  );
}

/**
 * React binding for a repository: loads once, keeps records in state, persists on change
 * and surfaces storage problems as a user-visible notice instead of a crash.
 */
import { useCallback, useEffect, useMemo, useState } from "react";
import type { Entity, Repository } from "../lib/repository.js";
import type { StorageStatus } from "../lib/storage.js";

export interface CollectionState<Record_ extends Entity> {
  records: Record_[];
  loading: boolean;
  status: StorageStatus;
  notice?: string;
  create: (input: Omit<Record_, keyof Entity>) => Record_;
  update: (id: string, changes: Partial<Omit<Record_, keyof Entity>>) => void;
  remove: (id: string) => void;
  replaceAll: (records: Record_[]) => void;
  dismissNotice: () => void;
}

export function useCollection<Record_ extends Entity>(
  repository: Repository<Record_>,
): CollectionState<Record_> {
  const [records, setRecords] = useState<Record_[]>([]);
  const [loading, setLoading] = useState(true);
  const [status, setStatus] = useState<StorageStatus>("empty");
  const [notice, setNotice] = useState<string | undefined>(undefined);

  useEffect(() => {
    const outcome = repository.load();
    setRecords(outcome.records);
    setStatus(outcome.status);
    setNotice(outcome.message);
    setLoading(false);
  }, [repository]);

  const commit = useCallback(
    (next: Record_[]) => {
      setRecords(next);
      const saved = repository.save(next);
      if (!saved.saved) {
        setStatus("unavailable");
        setNotice(saved.message);
      }
    },
    [repository],
  );

  const create = useCallback(
    (input: Omit<Record_, keyof Entity>) => {
      const created = repository.create(records, input);
      commit(created.records);
      return created.record;
    },
    [commit, records, repository],
  );

  const update = useCallback(
    (id: string, changes: Partial<Omit<Record_, keyof Entity>>) => {
      commit(repository.update(records, id, changes));
    },
    [commit, records, repository],
  );

  const remove = useCallback(
    (id: string) => {
      commit(repository.remove(records, id));
    },
    [commit, records, repository],
  );

  const replaceAll = useCallback(
    (next: Record_[]) => {
      commit(repository.replaceAll(next));
    },
    [commit, repository],
  );

  return useMemo(
    () => ({
      records,
      loading,
      status,
      ...(notice === undefined ? {} : { notice }),
      create,
      update,
      remove,
      replaceAll,
      dismissNotice: () => setNotice(undefined),
    }),
    [create, loading, notice, records, remove, replaceAll, status, update],
  );
}

/**
 * Repository boundary between domain records and persistence.
 *
 * The UI never touches storage directly: it calls a repository, which owns identifiers,
 * timestamps and persistence. Swapping localStorage for an HTTP client means replacing
 * this file only.
 */
import { createId } from "./id.js";
import { nowIso } from "./dates.js";
import { createStorage, type LoadOutcome, type StorageOptions, type Storage_ } from "./storage.js";

export interface Entity {
  id: string;
  created_at: string;
  updated_at: string;
}

export interface Repository<Record_ extends Entity> {
  storage: Storage_<Record_>;
  load: () => LoadOutcome<Record_>;
  list: (records: Record_[]) => Record_[];
  create: (records: Record_[], input: Omit<Record_, keyof Entity>) => { records: Record_[]; record: Record_ };
  update: (records: Record_[], id: string, changes: Partial<Omit<Record_, keyof Entity>>) => Record_[];
  remove: (records: Record_[], id: string) => Record_[];
  replaceAll: (records: Record_[]) => Record_[];
  save: (records: Record_[]) => { saved: boolean; message?: string };
  clear: () => void;
}

export interface RepositoryOptions<Record_ extends Entity> extends StorageOptions<Record_> {
  /** Optional stable ordering applied on every read. */
  compare?: (a: Record_, b: Record_) => number;
}

export function isEntityShape(value: unknown): value is Entity {
  if (typeof value !== "object" || value === null) return false;
  const record = value as Record<string, unknown>;
  return typeof record.id === "string" && record.id !== "";
}

export function createRepository<Record_ extends Entity>(
  key: string,
  options: RepositoryOptions<Record_>,
): Repository<Record_> {
  const storage = createStorage<Record_>(key, options);
  const order = (records: Record_[]): Record_[] =>
    options.compare ? [...records].sort(options.compare) : records;

  return {
    storage,
    load: () => {
      const outcome = storage.load();
      return { ...outcome, records: order(outcome.records) };
    },
    list: (records) => order(records),
    create: (records, input) => {
      const timestamp = nowIso();
      const record = { ...(input as object), id: createId(), created_at: timestamp, updated_at: timestamp } as Record_;
      return { records: order([...records, record]), record };
    },
    update: (records, id, changes) =>
      order(
        records.map((record) =>
          record.id === id ? ({ ...record, ...changes, updated_at: nowIso() } as Record_) : record,
        ),
      ),
    remove: (records, id) => records.filter((record) => record.id !== id),
    replaceAll: (records) => order(records),
    save: (records) => storage.save(records),
    clear: () => storage.clear(),
  };
}

/** Domain-neutral field validation. Rules are plain functions, composable per field. */

export type FieldRule<Value> = (value: Value) => string | undefined;
export type FieldErrors<Fields> = Partial<Record<keyof Fields, string>>;

export function required(message = "This field is required"): FieldRule<string> {
  return (value) => (value.trim() === "" ? message : undefined);
}

export function minLength(length: number, message?: string): FieldRule<string> {
  return (value) =>
    value.trim().length < length ? (message ?? `Use at least ${length} characters`) : undefined;
}

export function maxLength(length: number, message?: string): FieldRule<string> {
  return (value) =>
    value.trim().length > length ? (message ?? `Use at most ${length} characters`) : undefined;
}

export function pattern(expression: RegExp, message: string): FieldRule<string> {
  return (value) => (value.trim() === "" || expression.test(value.trim()) ? undefined : message);
}

export function isNumber(message = "Enter a number"): FieldRule<string> {
  return (value) => (value.trim() !== "" && Number.isNaN(Number(value)) ? message : undefined);
}

export function numberRange(min: number, max: number, message?: string): FieldRule<string> {
  return (value) => {
    if (value.trim() === "") return undefined;
    const parsed = Number(value);
    if (Number.isNaN(parsed)) return message ?? "Enter a number";
    return parsed < min || parsed > max ? (message ?? `Enter a value between ${min} and ${max}`) : undefined;
  };
}

export function oneOf(allowed: readonly string[], message = "Choose one of the options"): FieldRule<string> {
  return (value) => (allowed.includes(value) ? undefined : message);
}

/** Fails when another record already uses the same normalized value. */
export function unique(existing: readonly string[], message = "This already exists"): FieldRule<string> {
  const taken = new Set(existing.map((entry) => entry.trim().replaceAll(/\s+/gu, " ").toLowerCase()));
  return (value) => (taken.has(value.trim().replaceAll(/\s+/gu, " ").toLowerCase()) ? message : undefined);
}

export function firstError<Value>(value: Value, rules: readonly FieldRule<Value>[]): string | undefined {
  for (const rule of rules) {
    const error = rule(value);
    if (error) return error;
  }
  return undefined;
}

/** Runs every field's rules and returns only the fields that failed. */
export function validateFields<Fields extends Record<string, string>>(
  values: Fields,
  rules: { [Key in keyof Fields]?: readonly FieldRule<string>[] },
): FieldErrors<Fields> {
  const errors: FieldErrors<Fields> = {};
  for (const key of Object.keys(values) as (keyof Fields)[]) {
    const fieldRules = rules[key];
    if (!fieldRules) continue;
    const error = firstError(values[key], fieldRules);
    if (error) errors[key] = error;
  }
  return errors;
}

export function hasErrors<Fields>(errors: FieldErrors<Fields>): boolean {
  return Object.values(errors).some((entry) => typeof entry === "string" && entry !== "");
}

/** Test helpers for persistence and corruption scenarios. Domain-neutral by design. */

export function seedStorage(key: string, records: unknown[], version = 1): void {
  window.localStorage.setItem(key, JSON.stringify({ version, records }));
}

export function corruptStorage(key: string, raw = "{not json"): void {
  window.localStorage.setItem(key, raw);
}

export function readStorage<Record_>(key: string): { version: number; records: Record_[] } | undefined {
  const raw = window.localStorage.getItem(key);
  if (raw === null) return undefined;
  try {
    return JSON.parse(raw) as { version: number; records: Record_[] };
  } catch {
    return undefined;
  }
}

import "@testing-library/jest-dom/vitest";
import { afterEach, beforeEach } from "vitest";
import { cleanup } from "@testing-library/react";

// Every test starts from an empty, isolated browser store.
beforeEach(() => {
  window.localStorage.clear();
});

afterEach(() => {
  cleanup();
  window.localStorage.clear();
});

