.table td {
  padding: 0.55rem 0.6rem;
  border-bottom: 1px solid var(--border);
  vertical-align: top;
}

.grid {
  display: grid;
  gap: 0.75rem;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 12rem), 1fr));
}

/* Dialog */
.dialog__backdrop {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 1rem;
  background: rgb(14 20 35 / 45%);
}

.dialog {
  width: min(100%, 32rem);
  padding: 1.25rem;
  border-radius: 1rem;
  background: var(--surface);
}

.dialog__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.75rem;
}

.dialog__header h2 {
  margin: 0;
  font-size: 1.1rem;
}

.muted {
  color: var(--muted);
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #10151f;
    --surface: #161d2b;
    --border: #26314a;
    --text: #eef2fb;
    --muted: #a6b0c5;
    --accent: #7d9bff;
    --danger: #ff9a92;
    --success: #6edca0;
    --warning: #ffce7a;
  }
}

