import type { Entity } from "../lib/repository.js";
import {
  isNumber,
  maxLength,
  numberRange,
  oneOf,
  required,
  validateFields,
  type FieldErrors,
  type FieldRule,
} from "../lib/validation.js";

export const SUPPLY_TYPES = ["glaze", "clay", "tools"] as const;
export type SupplyType = (typeof SUPPLY_TYPES)[number];

export const SUPPLY_TYPE_LABELS: Record<SupplyType, string> = {
  glaze: "Glaze",
  clay: "Clay",
  tools: "Tools",
};

/** "A couple left" — anything at or below this count is flagged as running low. */
export const LOW_STOCK_THRESHOLD = 2;

export interface Supply extends Entity {
  name: string;
  supplier: string;
  type: SupplyType;
  quantity: number;
}

export interface SupplyInput {
  name: string;
  supplier: string;
  type: SupplyType;
  quantity: number;
}

const isSupplyType = (value: unknown): value is SupplyType =>
  typeof value === "string" && (SUPPLY_TYPES as readonly string[]).includes(value);

/** Accepts only well-formed records so damaged saved data is dropped, not crashed on. */
export function parseSupplyRecord(value: unknown): Supply | undefined {
  if (typeof value !== "object" || value === null) return undefined;
  const entry = value as Record<string, unknown>;
  if (typeof entry.id !== "string" || entry.id === "") return undefined;
  if (typeof entry.created_at !== "string" || typeof entry.updated_at !== "string") return undefined;
  if (typeof entry.name !== "string" || entry.name.trim() === "") return undefined;
  if (typeof entry.supplier !== "string") return undefined;
  if (!isSupplyType(entry.type)) return undefined;
  if (typeof entry.quantity !== "number" || !Number.isInteger(entry.quantity) || entry.quantity < 0) {
    return undefined;
  }
  return {
    id: entry.id,
    created_at: entry.created_at,
    updated_at: entry.updated_at,
    name: entry.name.trim(),
    supplier: entry.supplier.trim(),
    type: entry.type,
    quantity: entry.quantity,
  };
}

export function isLowStock(supply: Pick<Supply, "quantity">): boolean {
  return supply.quantity <= LOW_STOCK_THRESHOLD;
}

/** Low-stock items, most urgent first. */
export function lowStockSupplies(records: readonly Supply[]): Supply[] {
  return records
    .filter(isLowStock)
    .sort((a, b) => a.quantity - b.quantity || a.name.localeCompare(b.name));
}

export function countByType(records: readonly Supply[]): Record<SupplyType, number> {
  const counts: Record<SupplyType, number> = { glaze: 0, clay: 0, tools: 0 };
  for (const record of records) counts[record.type] += 1;
  return counts;
}

export interface SupplyFormValues {
  name: string;
  supplier: string;
  type: string;
  quantity: string;
}

const wholeQuantity: FieldRule<string> = (value) =>
  /^\d+$/.test(value.trim()) ? undefined : "Quantity must be a whole number of 0 or more";

export const supplyFormRules = {
  name: [required("Give this supply a name"), maxLength(80, "Keep the name under 80 characters")],
  supplier: [required("Add the supplier"), maxLength(80, "Keep the supplier under 80 characters")],
  type: [oneOf([...SUPPLY_TYPES], "Choose a type")],
  quantity: [
    required("Enter how many you have left"),
    isNumber(),
    wholeQuantity,
    numberRange(0, 100000, "Quantity must be between 0 and 100,000"),
  ],
};

export function validateSupplyForm(values: SupplyFormValues): FieldErrors<SupplyFormValues> {
  return validateFields(values, supplyFormRules);
}

export function toSupplyInput(values: SupplyFormValues): SupplyInput {
  return {
    name: values.name.trim(),
    supplier: values.supplier.trim(),
    type: values.type as SupplyType,
    quantity: Number(values.quantity.trim()),
  };
}

import { parseSupplyRecord, type Supply } from "../domain/supply.js";
import { createRepository } from "./repository.js";

export const SUPPLY_STORAGE_KEY = "pottery-studio-supplies";

export const supplyRepository = createRepository<Supply>(SUPPLY_STORAGE_KEY, {
  version: 1,
  parseRecord: parseSupplyRecord,
  compare: (a, b) => a.name.localeCompare(b.name) || a.supplier.localeCompare(b.supplier),
});

import { useState, type ChangeEvent, type FormEvent } from "react";
import {
  SUPPLY_TYPES,
  SUPPLY_TYPE_LABELS,
  toSupplyInput,
  validateSupplyForm,
  type Supply,
  type SupplyFormValues,
  type SupplyInput,
} from "../domain/supply.js";
import { Button, Form, SelectField, TextField } from "../ui/index.js";

const TYPE_OPTIONS = SUPPLY_TYPES.map((type) => ({ value: type, label: SUPPLY_TYPE_LABELS[type] }));

const EMPTY_VALUES: SupplyFormValues = { name: "", supplier: "", type: "glaze", quantity: "" };

export function SupplyForm({
  initial,
  submitLabel,
  onSubmit,
}: {
  initial?: Supply;
  submitLabel: string;
  onSubmit: (input: SupplyInput) => void;
}) {
  const [values, setValues] = useState<SupplyFormValues>(
    initial
      ? {
          name: initial.name,
          supplier: initial.supplier,
          type: initial.type,
          quantity: String(initial.quantity),
        }
      : EMPTY_VALUES,
  );
  const [errors, setErrors] = useState<Partial<Record<keyof SupplyFormValues, string>>>({});

  function setField(field: keyof SupplyFormValues) {
    return (event: ChangeEvent<HTMLInputElement | HTMLSelectElement>) =>
      setValues((current) => ({ ...current, [field]: event.target.value }));
  }

  function handleSubmit(event: FormEvent) {
    event.preventDefault();
    const nextErrors = validateSupplyForm(values);
    setErrors(nextErrors);
    if (Object.keys(nextErrors).length > 0) return;
    onSubmit(toSupplyInput(values));
    if (!initial) setValues(EMPTY_VALUES);
  }

  return (
    <Form onSubmit={handleSubmit}>
      <TextField
        label="Name"
        value={values.name}
        onChange={setField("name")}
        error={errors.name}
        placeholder="Cobalt blue glaze"
        autoComplete="off"
      />
      <TextField
        label="Supplier"
        value={values.supplier}
        onChange={setField("supplier")}
        error={errors.supplier}
        placeholder="Kiln & Co."
        autoComplete="off"
      />
      <SelectField
        label="Type"
        value={values.type}
        onChange={setField("type")}
        options={TYPE_OPTIONS}
        error={errors.type}
      />
      <TextField
        label="Quantity left"
        type="number"
        min={0}
        step={1}
        inputMode="numeric"
        value={values.quantity}
        onChange={setField("quantity")}
        error={errors.quantity}
        placeholder="12"
      />
      <div className="form__actions">
        <Button type="submit">{submitLabel}</Button>
      </div>
    </Form>
  );
}

import { isLowStock, SUPPLY_TYPE_LABELS, type Supply } from "../domain/supply.js";
import { Button, DataTable, EmptyState } from "../ui/index.js";

export function SupplyTable({
  supplies,
  onAdjust,
  onEdit,
  onDelete,
}: {
  supplies: readonly Supply[];
  onAdjust: (id: string, delta: number) => void;
  onEdit: (supply: Supply) => void;
  onDelete: (supply: Supply) => void;
}) {
  return (
    <DataTable
      caption="Supplies in the studio"
      rows={supplies}
      empty={<EmptyState title="Nothing here yet" description="Add a supply to see it in this list." />}
      columns={[
        { key: "name", header: "Name", render: (supply) => <strong>{supply.name}</strong> },
        { key: "supplier", header: "Supplier", render: (supply) => supply.supplier },
        { key: "type", header: "Type", render: (supply) => SUPPLY_TYPE_LABELS[supply.type] },
        {
          key: "quantity",
          header: "Quantity left",
          render: (supply) => (
            <span className="quantity">
              <Button
                variant="secondary"
                aria-label={`Decrease quantity of ${supply.name}`}
                onClick={() => onAdjust(supply.id, -1)}
                disabled={supply.quantity === 0}
              >
                −
              </Button>
              <span className="quantity__value">{supply.quantity}</span>
              <Button
                variant="secondary"
                aria-label={`Increase quantity of ${supply.name}`}
                onClick={() => onAdjust(supply.id, 1)}
              >
                +
              </Button>
            </span>
          ),
        },
        {
          key: "status",
          header: "Status",
          render: (supply) =>
            isLowStock(supply) ? (
              <span className="badge badge--low">Running low</span>
            ) : (
              <span className="badge badge--ok">OK</span>
            ),
        },
        {
          key: "actions",
          header: "Actions",
          render: (supply) => (
            <span className="row-actions">
              <Button variant="secondary" onClick={() => onEdit(supply)}>
                Edit
              </Button>
              <Button variant="danger" onClick={() => onDelete(supply)}>
                Delete
              </Button>
            </span>
          ),
        },
      ]}
    />
  );
}

import {
  LOW_STOCK_THRESHOLD,
  lowStockSupplies,
  SUPPLY_TYPE_LABELS,
  type Supply,
} from "../domain/supply.js";
import { DataList, EmptyState, Section } from "../ui/index.js";

export function LowStockPanel({ supplies }: { supplies: readonly Supply[] }) {
  const low = lowStockSupplies(supplies);
  return (
    <Section
      title="Running low"
      actions={<span className="muted">at or below {LOW_STOCK_THRESHOLD} left</span>}
    >
      <DataList
        label="Supplies running low"
        items={low}
        empty={
          <EmptyState
            title="Nothing is running low"
            description={`Every supply has more than ${LOW_STOCK_THRESHOLD} left.`}
          />
        }
        renderItem={(supply) => (
          <div className="low-item">
            <span className="low-item__name">{supply.name}</span>
            <span className="muted">
              {SUPPLY_TYPE_LABELS[supply.type]} · {supply.supplier}
            </span>
            <span className="badge badge--low">{supply.quantity} left</span>
          </div>
        )}
      />
    </Section>
  );
}

import { useMemo, useState } from "react";
import { LowStockPanel } from "./components/LowStockPanel.js";
import { SupplyForm } from "./components/SupplyForm.js";
import { SupplyTable } from "./components/SupplyTable.js";
import {
  countByType,
  lowStockSupplies,
  SUPPLY_TYPES,
  SUPPLY_TYPE_LABELS,
  type Supply,
  type SupplyInput,
  type SupplyType,
} from "./domain/supply.js";
import { useCollection } from "./hooks/useCollection.js";
import { supplyRepository } from "./lib/supplyRepository.js";
import { AppShell, Button, Dialog, EmptyState, Notice, Section, StatCard } from "./ui/index.js";

type TypeFilter = "all" | SupplyType;

const FILTER_LABELS: Record<TypeFilter, string> = {
  all: "All",
  glaze: "Glazes",
  clay: "Clay",
  tools: "Tools",
};

const EMPTY_FILTER_NOUN: Record<SupplyType, string> = { glaze: "glaze", clay: "clay", tools: "tool" };

export function App() {
  const collection = useCollection(supplyRepository);
  const [filter, setFilter] = useState<TypeFilter>("all");
  const [editing, setEditing] = useState<Supply | null>(null);
  const [flash, setFlash] = useState<string | undefined>(undefined);

  const { records } = collection;
  const counts = useMemo(() => countByType(records), [records]);
  const lowCount = useMemo(() => lowStockSupplies(records).length, [records]);
  const visible = useMemo(
    () => (filter === "all" ? records : records.filter((supply) => supply.type === filter)),
    [records, filter],
  );

  function handleCreate(input: SupplyInput) {
    const created = collection.create(input);
    setFlash(`Added ${created.name}.`);
  }

  function handleEditSubmit(input: SupplyInput) {
    if (!editing) return;
    collection.update(editing.id, input);
    setFlash(`Updated ${input.name}.`);
    setEditing(null);
  }

  function handleDelete(supply: Supply) {
    collection.remove(supply.id);
    setFlash(`Deleted ${supply.name}.`);
  }

  function handleAdjust(id: string, delta: number) {
    const target = records.find((supply) => supply.id === id);
    if (!target) return;
    collection.update(id, { quantity: Math.max(0, target.quantity + delta) });
  }

  const filterOptions: { value: TypeFilter; count: number }[] = [
    { value: "all", count: records.length },
    ...SUPPLY_TYPES.map((type) => ({ value: type as TypeFilter, count: counts[type] })),
  ];

  return (
    <AppShell
      title="Studio Supplies"
      description="Track your glazes, clay and tools, and spot what is running low before it runs out."
    >
      {collection.notice ? (
        <Notice tone="warning" onDismiss={collection.dismissNotice}>
          {collection.notice}
        </Notice>
      ) : null}
      {flash ? <Notice tone="success">{flash}</Notice> : null}

      <div className="grid grid--stats" role="group" aria-label="Supply totals">
        <StatCard label="Supplies tracked" value={records.length} />
        <StatCard label="Running low" value={lowCount} />
        <StatCard label="Glazes" value={counts.glaze} />
        <StatCard label="Clay" value={counts.clay} />
        <StatCard label="Tools" value={counts.tools} />
      </div>

      <LowStockPanel supplies={records} />

      <Section title="Add a supply">
        <SupplyForm submitLabel="Add supply" onSubmit={handleCreate} />
      </Section>

      <Section
        title="Supplies"
        actions={
          <div className="filter" role="group" aria-label="Filter supplies by type">
            {filterOptions.map((option) => (
              <Button
                key={option.value}
                variant={filter === option.value ? "primary" : "secondary"}
                aria-pressed={filter === option.value}
                onClick={() => setFilter(option.value)}
              >
                {FILTER_LABELS[option.value]} ({option.count})
              </Button>
            ))}
          </div>
        }
      >
        {visible.length === 0 ? (
          <EmptyState
            title={
              records.length === 0
                ? "No supplies yet"
                : `No ${EMPTY_FILTER_NOUN[filter as SupplyType]} supplies`
            }
            description={
              records.length === 0
                ? "Add your first supply above to start tracking."
                : "Try a different type filter."
            }
          />
        ) : (
          <SupplyTable
            supplies={visible}
            onAdjust={handleAdjust}
            onEdit={setEditing}
            onDelete={handleDelete}
          />
        )}
      </Section>

      <Dialog
        open={editing !== null}
        title={editing ? `Edit ${editing.name}` : "Edit supply"}
        onClose={() => setEditing(null)}
      >
        {editing ? (
          <SupplyForm
            key={editing.id}
            initial={editing}
            submitLabel="Save changes"
            onSubmit={handleEditSubmit}
          />
        ) : null}
      </Dialog>
    </AppShell>
  );
}

